CREATE TABLE public.ai_service_blocks(model text PRIMARY KEY,status integer NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());GRANT ALL ON public.ai_service_blocks TO service_role;ALTER TABLE public.ai_service_blocks ENABLE ROW LEVEL SECURITY;CREATE POLICY ai_block_server ON public.ai_service_blocks FOR ALL TO service_role USING(true) WITH CHECK(true);CREATE TRIGGER ai_block_touch BEFORE UPDATE ON public.ai_service_blocks FOR EACH ROW EXECUTE FUNCTION public.touch_ai_record();CREATE FUNCTION public.reconcile_ai_request(p_conversation uuid,p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.ai_conversations;r public.ai_requests;BEGIN SELECT * INTO c FROM public.ai_conversations WHERE id=p_conversation AND user_id=p_user FOR UPDATE;IF c.id IS NULL THEN RETURN jsonb_build_object('state','Unavailable');END IF;IF c.busy_request IS NULL THEN RETURN jsonb_build_object('state','Ready');END IF;SELECT * INTO r FROM public.ai_requests WHERE id=c.busy_request;IF r.status IN ('Completed','Failed','Stopped') THEN UPDATE public.ai_conversations SET busy_request=NULL WHERE id=c.id;RETURN jsonb_build_object('state','Ready');END IF;RETURN jsonb_build_object('state',CASE WHEN r.heartbeat_at<now()-interval '15 minutes' THEN 'Needs reconciliation' ELSE 'Running' END,'message','An earlier request may still be processing. Review saved results; billed work is never automatically replayed.');END $$;REVOKE ALL ON FUNCTION public.reconcile_ai_request(uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.reconcile_ai_request(uuid,uuid) TO service_role;